const b = $input.first().json.body || $input.first().json || {};
const action = String(b.action || 'get_stats');
if ($env.MONGODB_URI && (action === 'get_stats' || action === 'list_leads')) {
  try {
    const { MongoClient } = require('mongodb');
    const client = new MongoClient($env.MONGODB_URI);
    await client.connect();
    const db = client.db($env.MONGODB_DB || 'tradesejon_prod');
    if (action === 'list_leads') {
      const leads = await db.collection('leads').find({}).sort({ createdAt: -1 }).limit(50).toArray();
      await client.close();
      return [{ json: { ok: true, count: leads.length, leads } }];
    }
    const totalLeads = await db.collection('leads').countDocuments();
    const activeMembers = await db.collection('members').countDocuments({ active: true });
    await client.close();
    return [{ json: { ok: true, total_leads: totalLeads, active_members: activeMembers } }];
  } catch (e) {
    return [{ json: { ok: false, error: 'Database query failed: ' + e.message } }];
  }
}
const capital = Number(b.capital || 0);
const score = Math.min(40 + (capital >= 1000 ? 35 : (capital >= 250 ? 20 : 0)) + (['advanced','intermediate'].includes(String(b.trading_level).toLowerCase()) ? 25 : 0), 100);
return [{ json: { ok: true, action, lead_score: score, tier: score >= 75 ? 'VIP_HOT_LEAD' : 'QUALIFIED_PROSPECT' } }];
